3	namespace App\Jobs\Streaming;
4	
5	use App\Models\Core\Site\Block;
6	use App\Services\Streaming\LiveStatusPoller;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	use Illuminate\Support\Facades\Redis;
14	
15	// Polls Twitch and Kick every 2 minutes for live status of all blocks with live_check_enabled=true.
16	class CheckStreamingLiveStatusJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 1;
21	
22	    public int $timeout = 90;
23	
24	    public function handle(LiveStatusPoller $poller): void
25	    {
26	        try {
27	            $kickRateLimited = Redis::exists('streaming:kick:rate_limited');
28	        } catch (\Throwable $e) {
29	            Log::critical('streaming.redis_unavailable', ['message' => $e->getMessage()]);
30	
31	            return;
32	        }
33	
34	        if ($kickRateLimited) {
35	            Log::warning('streaming: skipping Kick — rate limited from previous cycle');
36	        }
37	
38	        $streamingPlatforms = config('sidest.streaming_platforms', []);
39	
40	        /** @var array<string, list<string>> $handlesByPlatform */
41	        $handlesByPlatform = array_fill_keys($streamingPlatforms, []);
42	
43	        // block_group='links' (NOT block_type='link') is the links/sections discriminator
44	        // in site.blocks. All other queries in the codebase use block_group.
45	        Block::query()
46	            ->where('block_group', 'links')
47	            ->whereRaw("settings->>'live_check_enabled' = ?", ['true'])
48	            ->whereNull('deleted_at')
49	            ->where('is_active', true)
50	            ->chunkById(500, function ($blocks) use (&$handlesByPlatform, $streamingPlatforms): void {
51	                foreach ($blocks as $block) {
52	                    $settings = is_array($block->settings) ? $block->settings : [];
53	                    $platform = $settings['platform'] ?? null;
54	                    $handle = $settings['handle'] ?? null;
55	
56	                    if (
57	                        $platform
58	                        && $handle
59	                        && in_array($platform, $streamingPlatforms, true)
60	                    ) {
61	                        $handlesByPlatform[$platform][] = $handle;
62	                    }
63	                }
64	            });
65	
66	        foreach ($handlesByPlatform as $platform => $handles) {
67	            if (empty($handles)) {
68	                continue;
69	            }
70	
71	            if ($platform === 'kick' && $kickRateLimited) {
72	                continue;
73	            }
74	
75	            try {
76	                $poller->poll($platform, $handles);
77	            } catch (\Throwable $e) {
78	                Log::error('streaming.poll_error', [
79	                    'platform' => $platform,
80	                    'message' => $e->getMessage(),
81	                ]);
82	            }
83	        }
84	    }
85	
86	    public function failed(\Throwable $e): void
87	    {
88	        Log::error('streaming.job_failed', ['message' => $e->getMessage()]);
89	    }
90	}
