90	final class NightwatchServiceProvider extends ServiceProvider
91	{
92	    /**
93	     * @var Core<RequestState|CommandState>
94	     */
95	    private Core $core;
96	
97	    private float $timestamp;
98	
99	    private bool $isRequest;
100	
101	    private Repository $config;
102	
103	    /**
104	     * @var array{
105	     *     enabled?: bool,
106	     *     sampling?: array{
107	     *        requests?: float,
108	     *        commands?: float,
109	     *        exceptions?: float,
110	     *        scheduled_tasks?: float,
111	     *     },
112	     *     filtering?: array{
113	     *         ignore_cache_events?: bool,
114	     *         ignore_mail?: bool,
115	     *         ignore_notifications?: bool,
116	     *         ignore_outgoing_requests?: bool,
117	     *         ignore_queries?: bool,
118	     *         log_level?: \Psr\Log\LogLevel::*,
119	     *     },
120	     *     token?: string,
121	     *     deployment?: string,
122	     *     server?: string,
123	     *     ingest?: array{ uri?: string, timeout?: float|int, connection_timeout?: float|int, event_buffer?: int },
124	     *     capture_exception_source_code?: bool,
125	     *     capture_request_payload?: bool,
126	     *     redact_payload_fields?: string[],
127	     *     redact_headers?: string[],
128	     *  }
129	     */
130	    private array $nightwatchConfig;
131	
132	    private ?Throwable $registerException = null;
133	
134	    public function register(): void
135	    {
136	        try {
137	            $this->captureTimestamp();
138	            Compatibility::boot($this->app);
139	            $this->captureExecutionType();
140	            $this->registerAndCaptureConfig();
141	            $this->registerBindings();
142	
143	            if (! $this->core->enabled()) {
144	                return;
145	            }
146	
147	            $this->registerHooks();
148	        } catch (Throwable $e) {
149	            $this->registerException = $e;
150	        }
151	    }
152	
153	    public function boot(): void
154	    {
155	        try {
156	            if ($this->registerException) {
157	                $this->handleAndClearRegisterException();
158	
159	                return;
160	            }
161	
162	            if ($this->app->runningInConsole()) {
163	                $this->registerPublications();
164	                $this->registerCommands();
165	            }
166	        } catch (Throwable $e) {
167	            Nightwatch::unrecoverableExceptionOccurred($e);
168	        }
169	    }
170	
171	    private function captureTimestamp(): void
172	    {
173	        $this->timestamp = match (true) {
174	            defined('LARAVEL_START') => LARAVEL_START,
175	            default => $_SERVER['REQUEST_TIME_FLOAT'] ?? microtime(true),
176	        };
177	    }
178	
179	    private function captureExecutionType(): void
180	    {
181	        $this->isRequest = ! $this->app->runningInConsole() || Env::get('NIGHTWATCH_FORCE_REQUEST');
182	    }
183	
184	    private function registerAndCaptureConfig(): void
185	    {
186	        $this->mergeConfigFrom(__DIR__.'/../config/nightwatch.php', 'nightwatch');
187	
188	        $this->config = $this->app->make(Repository::class);
189	
190	        $this->nightwatchConfig = $this->config->get('nightwatch') ?? []; // @phpstan-ignore assign.propertyType
191	    }
192	
193	    private function registerBindings(): void
194	    {
195	        $this->registerLogger();
196	        $this->registerMiddleware();
197	        $this->registerAgentCommand();
198	        $this->buildAndRegisterCore();
199	    }
200	
201	    private function registerLogger(): void
202	    {
203	        if (! $this->config->has('logging.channels.nightwatch')) {
204	            $this->config->set('logging.channels.nightwatch', [
205	                'driver' => 'custom',
206	                'via' => Logger::class,
207	                'level' => $this->nightwatchConfig['filtering']['log_level'] ?? 'debug',
208	            ]);
209	        }
210	
211	        $this->app->singleton(Logger::class, fn () => new Logger($this->core));
212	    }
213	
214	    private function registerMiddleware(): void
215	    {
216	        $this->app->singleton(RouteMiddleware::class, fn () => new RouteMiddleware($this->core)); // @phpstan-ignore argument.type
217	
218	        $this->app->scoped(GlobalMiddleware::class, fn () => new GlobalMiddleware($this->core)); // @phpstan-ignore argument.type
219	
220	        $this->app->singleton(Sample::class, fn () => new Sample($this->core)); // @phpstan-ignore argument.type
221	    }
222	
223	    private function registerAgentCommand(): void
224	    {
225	        $this->app->singleton(AgentCommand::class, fn () => new AgentCommand(
226	            token: $this->nightwatchConfig['token'] ?? null,
227	            server: $this->nightwatchConfig['server'] ?? null,
228	            ingestUri: $this->nightwatchConfig['ingest']['uri'] ?? null,
229	        ));
230	    }
231	
232	    private function buildAndRegisterCore(): void
233	    {
234	        $clock = new Clock;
235	        $uuid = new Uuid(static fn () => BaseUuid::uuid4()->toString());
236	        $executionState = $this->executionState($uuid->make());
237	        $tokenHash = substr(hash('xxh128', $this->nightwatchConfig['token'] ?? ''), 0, 7);
238	
239	        $this->app->instance(Core::class, $this->core = new Core(
240	            ingest: new Ingest(
241	                transmitTo: $this->nightwatchConfig['ingest']['uri'] ?? '127.0.0.1:2407',
242	                connectionTimeout: $this->nightwatchConfig['ingest']['connection_timeout'] ?? 0.5,
243	                timeout: $this->nightwatchConfig['ingest']['timeout'] ?? 0.5,
244	                streamFactory: new SocketStreamFactory,
245	                buffer: new RecordsBuffer(
