128	        }
129	
130	        $jwks = $this->cacheLock->rememberLocked('supabase:jwks', config('supabase.jwks_cache_seconds', 300), function () use ($jwksUrl) {
131	            $res = Http::timeout(5)->get($jwksUrl);
132	            if (! $res->ok()) {
