136	            $payload = $res->json();
137	            if (! is_array($payload)) {
138	                // Empty/invalid JSON body — never cache this. Throwing keeps the lock-release
139	                // path clean and lets the caller's error logging surface the infra problem.
140	                throw new \RuntimeException('JWKS response did not parse to an array');
