164	    private function verifyWithAuthServer(string $jwt): ?string
165	    {
166	        $baseUrl = rtrim((string) config('supabase.url'), '/');
167	        $anonKey = (string) config('supabase.anon_key');
168	
169	        if (! $baseUrl || ! $anonKey) {
170	            throw new \RuntimeException('Missing SUPABASE_URL or SUPABASE_ANON_KEY');
171	        }
172	
173	        // Validate iss/aud from the token payload before calling Auth-Server.
174	        // Auth-Server verifies the signature, but doesn't protect against cross-project
175	        // tokens (a valid token from another Supabase project would pass otherwise).
176	        $claims = $this->extractJwtPayloadClaims($jwt);
177	        if (! $this->claimsMatchConfig($claims)) {
178	            return null;
179	        }
180	
181	        $res = Http::timeout(5)
182	            ->withHeaders([
183	                'apikey' => $anonKey,
184	                'Authorization' => 'Bearer '.$jwt,
185	            ])
186	            ->get($baseUrl.'/auth/v1/user');
187	
188	        if (! $res->ok()) {
189	            return null;
190	        }
