227	
228	        $aud = $claims['aud'] ?? null;
229	        if ($audExpected) {
230	            if (is_array($aud)) {
231	                if (! in_array($audExpected, $aud, true)) {
232	                    return false;
233	                }
234	            } else {
235	                if ($aud !== $audExpected) {
236	                    return false;
237	                }
238	            }
239	        }
240	
241	        return true;
242	    }
