244	    private function b64urlDecode(string $data): string
245	    {
246	        $data = strtr($data, '-_', '+/');
247	        $pad = strlen($data) % 4;
248	        if ($pad) {
249	            $data .= str_repeat('=', 4 - $pad);
250	        }
251	
252	        return base64_decode($data) ?: '';
